// HasOrder applies the HasEdge predicate on the "order" edge.
func HasOrder() predicate.PaymentAttempt {
	return predicate.PaymentAttempt(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, OrderTable, OrderColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasOrderWith applies the HasEdge predicate on the "order" edge with a given conditions (other predicates).
func HasOrderWith(preds ...predicate.CommerceOrder) predicate.PaymentAttempt {
	return predicate.PaymentAttempt(func(s *sql.Selector) {
		step := newOrderStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasFacts applies the HasEdge predicate on the "facts" edge.
func HasFacts() predicate.PaymentAttempt {
	return predicate.PaymentAttempt(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, FactsTable, FactsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasFactsWith applies the HasEdge predicate on the "facts" edge with a given conditions (other predicates).
func HasFactsWith(preds ...predicate.PaymentFact) predicate.PaymentAttempt {
	return predicate.PaymentAttempt(func(s *sql.Selector) {
		step := newFactsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.PaymentAttempt) predicate.PaymentAttempt {
	return predicate.PaymentAttempt(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.PaymentAttempt) predicate.PaymentAttempt {
	return predicate.PaymentAttempt(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.PaymentAttempt) predicate.PaymentAttempt {
	return predicate.PaymentAttempt(sql.NotPredicates(p))
}
